                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        elif expr[i] in '+-*/()':
            tokens.append(expr[i])
            i += 1
        else:
            i += 1

    pos = 0

    def parse_expr():
        nonlocal pos
        left = parse_term()
        while pos < len(tokens) and tokens[pos] in ['+', '-']:
            op = tokens[pos]
            pos += 1
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_term():
        nonlocal pos
        left = parse_unary()
        while pos < len(tokens) and tokens[pos] in ['*', '/']:
            op = tokens[pos]
            pos += 1
            right = parse_unary()
            if op == '*':
                left = left * right
            else:
                left = int(left / right)
        return left

    def parse_unary():
        nonlocal pos
        if pos < len(tokens) and tokens[pos] == '-':
            pos += 1
            return -parse_unary()
        elif pos < len(tokens) and tokens[pos] == '+':
            pos += 1
            return parse_unary()
        else:
            return parse_primary()

    def parse_primary():
        nonlocal pos
        if pos < len(tokens) and tokens[pos] == '(':
            pos += 1
            result = parse_expr()
            pos += 1
            return result
        elif pos < len(tokens) and isinstance(tokens[pos], int):
            result = tokens[pos]
            pos += 1
            return result
        return 0

    return parse_expr()

